import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { decryptJwe, decryptIdToken, verifyIdToken, openServerData, openWebhook } from '../dist/delivery.js';
import { verifyWebhook } from '../dist/index.js';

// SDK/go/testdata/vectors.json is shared by every SDK (generated by the backend delivery module).
const set = JSON.parse(readFileSync(new URL('../../go/testdata/vectors.json', import.meta.url), 'utf8'));
const all = [set.keys.rsa, set.keys.ec, set.keys.x25519];
const iss = 'https://account.example.com';
const aud = 'vector-app';

for (const v of set.vectors) {
  test(`vector ${v.name}`, async () => {
    if (v.fail) {
      await assert.rejects(decryptJwe(v.compact, set.keys[v.key]));
      return;
    }
    assert.equal((await decryptJwe(v.compact, set.keys[v.key])).text, v.plaintext);
    assert.equal((await decryptJwe(v.compact, all)).text, v.plaintext, 'kid selection among keys');
    if (v.kind === 'id_token') {
      const claims = await decryptIdToken(v.compact, all, set.signing, { issuer: iss, audience: aud });
      assert.equal(claims.name, '旅行者');
      assert.equal(claims.nonce, 'n-vector');
      await assert.rejects(verifyIdToken(v.plaintext, set.signing, { issuer: iss, audience: 'other-app' }));
    }
    if (v.kind === 'server') {
      assert.deepEqual(await openServerData(v.response, set.keys[v.key], v.ctx), JSON.parse(v.plaintext));
      await assert.rejects(openServerData(v.response, set.keys[v.key], 'server:other:whitelist'));
      await assert.rejects(openServerData({ code: 0, data: { server: 'x' } }, set.keys[v.key]));
    }
    if (v.kind === 'webhook') {
      await verifyWebhook(v.secret, v.headers, v.body, 0);
      const ev = await openWebhook(v.body, set.keys[v.key]);
      assert.equal(ev.id, 'evt-vector');
      assert.equal(ev.data.user.nickname, '旅行者');
    }
  });
}

test('wrong key is refused', async () => {
  await assert.rejects(decryptJwe(set.vectors[0].compact, set.keys.ec));
});
